import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { batchLinksWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await batchLinksWorkflow(req.scope)
    .run({
      input: {
        create: [{
          // import { Modules } from "@medusajs/framework/utils"
          [Modules.PRODUCT]: {
            product_id: "prod_123",
          },
          "helloModuleService": {
            my_custom_id: "mc_123",
          },
        }],
        update: [{
          // import { Modules } from "@medusajs/framework/utils"
          [Modules.PRODUCT]: {
            product_id: "prod_321",
          },
          "helloModuleService": {
            my_custom_id: "mc_321",
          },
          data: {
            metadata: {
              test: false
            }
          }
        }],
        delete: [{
          // import { Modules } from "@medusajs/framework/utils"
          [Modules.PRODUCT]: {
            product_id: "prod_321",
          },
        }]
      }
    })

  res.send(result)
}

